text:
  }
  document.getElementById("keyEncAlgorithm").textContent = gKeyEncAlgorithm;

  // Hide the whole section when empty, and always start collapsed.
  details.hidden = !haveSig && !haveEnc;
  details.open = false;
}

/**
 * Empty and hide the cryptographic details section. Called when switching to
 * a new message so no stale algorithm information remains on screen.
 */
function clearCryptoDetails() {
  const details = document.getElementById("cryptoDetails");
  if (!details) {
    return;
  }

  document.getElementById("signatureCryptoDetails").collapsed = true;
  document.getElementById("sigAlgorithm").textContent = "";
  document.getElementById("sigDigestAlgorithm").textContent = "";

  document.getElementById("encryptionCryptoDetails").collapsed = true;
  const encAlgEl = document.getElementById("encAlgorithm");
  encAlgEl.removeAttribute("data-l10n-id");
  encAlgEl.removeAttribute("data-l10n-args");
  encAlgEl.textContent = "";
  document.getElementById("keyEncAlgorithm").textContent = "";

  details.hidden = true;
  details.open = false;
}

/**
 * Open UI that displays the given certificate.
 * or subdirectory of the given special system/app directory (aDirToCheck).
 *
 * @param {nsIX509Cert} cert - The certificate to display.
 */
async function viewCert(cert) {
  const url = await getCertViewerUrl(cert);
  const mail3PaneWindow = Services.wm.getMostRecentWindow("mail:3pane");
  mail3PaneWindow.switchToTabHavingURI(url, true, {});
}

async function viewSignatureCert(popupToHide) {
  if (popupToHide) {
    popupToHide.hidePopup();
  }

  if (gSignerCert) {
    viewCert(gSignerCert);
  }
}

function viewEncryptionCert(popupToHide) {
  if (popupToHide) {
    popupToHide.hidePopup();
  }

  if (gEncryptionCert) {
    viewCert(gEncryptionCert);
  }
}

/**
 * Map a signature verification failure reason to the appropriate
 * error message string name.
 *
 * @param {nsISMimeVerificationFailure} reason
 *
 * @returns {string}
 */
function mapSignatureFailureReason(reason) {
  if (!reason) {
    return "SIClueless";
  }

  switch (reason.enumString) {
    case "Result::ERROR_EXPIRED_CERTIFICATE":
      return "SIExpired";
    case "Result::ERROR_REVOKED_CERTIFICATE":
      return "SIRevoked";
    case "Result::ERROR_NOT_YET_VALID_CERTIFICATE":
      return "SINotYetValid";
    case "Result::ERROR_UNKNOWN_ISSUER":
      return "SIUnknownCA";
    case "Result::ERROR_EXPIRED_ISSUER_CERTIFICATE":
      return "SIExpiredCA";
    case "Result::ERROR_ISSUER_NO_LONGER_TRUSTED":
      return "SIRevokedCA";
    case "Result::ERROR_NOT_YET_VALID_ISSUER_CERTIFICATE":
      return "SINotYetValidCA";
    case "Result::ERROR_UNTRUSTED_ISSUER":
      return "SIUntrustedCA";
    default:
      return "SIClueless";
  }
}
